"""Resolve a logical training record through the current dataset catalog."""

import json
from pathlib import Path


def resolve(root, record):
    root = Path(root)
    catalog = json.loads(root.joinpath("catalog.json").read_text())
    for row in catalog.get("rows", []):
        if row.get("id") == record.get("id") and row.get("sha256") == record.get("sha256"):
            candidate = root.joinpath(row.get("path"))
            if candidate.is_file():
                return str(candidate.relative_to(root))
    raise FileNotFoundError("record unavailable")

